import React, {
    useRef,
    useState,
    useEffect
} from 'react'

import {
    Text,
    Animated,
    TouchableOpacity,
    View
} from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles'

export function Alert() {
    const [active, setActive] = useState(false);
    const fadeAnim = useRef(new Animated.Value(0)).current;

    const {
        alertMessage,
        alertActive
    } = useContexState();

    const {
        setAlertActive,
    } = useContexState();


    function AnimatedAlert(value: boolean) {
        setActive(true);
        Animated.timing(fadeAnim, {
            toValue: value ? 1 : 0,
            duration: 700,
        } as Animated.TimingAnimationConfig).start(() => {
            if (!value) {
                setActive(false)
            };
        });
    };


    useEffect(() => {
        AnimatedAlert(alertActive);
    }, [alertActive]);


    return active ? <>
        <TouchableOpacity
            onPress={() => setAlertActive(false)}
            style={styles.container} />
        <Animated.View style={[styles.containerAlert, { opacity: fadeAnim }]} >
            <Text style={styles.listText}>{alertMessage}</Text>
        </Animated.View>
    </> : <View />
};
